def solid_squares_mask(grid, m=5):
    """1 for every cell that lies in some m x m square of one color, else 0."""
    h, w = len(grid), len(grid[0])
    res = [[0] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            c = grid[i][j]
            for di in range(-m + 1, 1):
                for dj in range(-m + 1, 1):
                    ti, tj = i + di, j + dj
                    if 0 <= ti and ti + m <= h and 0 <= tj and tj + m <= w \
                            and all(grid[ti + a][tj + b] == c for a in range(m) for b in range(m)):
                        res[i][j] = 1
                        break
                else:
                    continue
                break
    return res

def recolor_solid_squares(grid, m=5, new=4):
    """Every cell inside an m x m (or larger) one-color square becomes new."""
    mask = solid_squares_mask(grid, m)
    return [[new if mask[i][j] else v for j, v in enumerate(row)] for i, row in enumerate(grid)]

def run_lengths(grid):
    """For each cell, the length of the vertical and of the horizontal run of its color through it."""
    h, w = len(grid), len(grid[0])
    up = [[1] * w for _ in range(h)]
    dn = [[1] * w for _ in range(h)]
    lf = [[1] * w for _ in range(h)]
    rt = [[1] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if i and grid[i - 1][j] == grid[i][j]: up[i][j] = up[i - 1][j] + 1
            if j and grid[i][j - 1] == grid[i][j]: lf[i][j] = lf[i][j - 1] + 1
    for i in range(h - 1, -1, -1):
        for j in range(w - 1, -1, -1):
            if i + 1 < h and grid[i + 1][j] == grid[i][j]: dn[i][j] = dn[i + 1][j] + 1
            if j + 1 < w and grid[i][j + 1] == grid[i][j]: rt[i][j] = rt[i][j + 1] + 1
    return [[(up[i][j] + dn[i][j] - 1, lf[i][j] + rt[i][j] - 1) for j in range(w)] for i in range(h)]

def recolor_cross_runs(grid, m=5, new=4):
    """Every cell whose vertical and horizontal same-color runs are both at least m becomes new."""
    rl = run_lengths(grid)
    return [[new if rl[i][j][0] >= m and rl[i][j][1] >= m else v for j, v in enumerate(row)]
            for i, row in enumerate(grid)]
